import{i as e,r as t,s as n,t as r}from"./app-D1trhGny.js";import"./domain-forest-BIwFFaw0.js";var i=JSON.parse(`{"path":"/pentest/domain/domain.html","title":"内网域控","lang":"zh-CN","frontmatter":{"description":"内网域控 什么是 Windows 域 Windows 域，是计算机网络的一种形式，其中所有的用户账户、计算机、打印机和其它网络设备都被域控制器管理，方便管理员管理，配置大量的主机设备。 域类型 单域 在一个域内，一般至少需要两台域服务器，一台作为 DC，一台作为备份 DC。 域树 域 DC 域控 域控制器（Domain Control）在域架构中用来管...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"内网域控\\",\\"image\\":[\\"https://deelmind.com/imgs/web/inner/domain/domain-forest.png\\"],\\"dateModified\\":\\"2026-03-11T05:49:26.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"DeeLMind\\",\\"url\\":\\"https://deelmind.com\\"}]}"],["meta",{"property":"og:url","content":"https://deelmind.com/pentest/domain/domain.html"}],["meta",{"property":"og:site_name","content":"極客方舟"}],["meta",{"property":"og:title","content":"内网域控"}],["meta",{"property":"og:description","content":"内网域控 什么是 Windows 域 Windows 域，是计算机网络的一种形式，其中所有的用户账户、计算机、打印机和其它网络设备都被域控制器管理，方便管理员管理，配置大量的主机设备。 域类型 单域 在一个域内，一般至少需要两台域服务器，一台作为 DC，一台作为备份 DC。 域树 域 DC 域控 域控制器（Domain Control）在域架构中用来管..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://deelmind.com/imgs/web/inner/domain/domain-forest.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-03-11T05:49:26.000Z"}],["meta",{"property":"article:modified_time","content":"2026-03-11T05:49:26.000Z"}]]},"git":{"createdTime":1734955114000,"updatedTime":1773208166000,"contributors":[{"name":"DeeLMind","username":"DeeLMind","email":"deelmind@gmail.com","commits":2,"url":"https://github.com/DeeLMind"}]},"readingTime":{"minutes":1.98,"words":595},"filePathRelative":"pentest/domain/domain.md","autoDesc":true}`),a={name:`domain.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="内网域控" tabindex="-1"><a class="header-anchor" href="#内网域控"><span>内网域控</span></a></h1><h2 id="什么是-windows-域" tabindex="-1"><a class="header-anchor" href="#什么是-windows-域"><span>什么是 Windows 域</span></a></h2><p><a href="https://docs.microsoft.com/en-us/windows-server/identity/ad-ds/get-started/virtual-dc/active-directory-domain-services-overview" target="_blank" rel="noopener noreferrer">Windows 域</a>，是计算机网络的一种形式，其中所有的用户账户、计算机、打印机和其它网络设备都被域控制器管理，方便管理员管理，配置大量的主机设备。</p><h2 id="域类型" tabindex="-1"><a class="header-anchor" href="#域类型"><span>域类型</span></a></h2><ul><li>单域</li></ul><p>在一个域内，一般至少需要两台域服务器，一台作为 DC，一台作为备份 DC。</p><ul><li>域树</li></ul><p><img src="/imgs/web/inner/domain/domain-forest.png" alt="域"></p><ul><li>DC 域控</li></ul><p>域控制器（Domain Control）在域架构中用来管理所有客户端的服务器，是域架构的核心，每个域控制器上都包含了 AD 活动目录数据库,即安装了 AD 的服务器就是域控 DC。一般内网中存在多个域控，且域控之间可以自动同步信息，从而确保域的安全运行。</p><ul><li><p>信任域</p></li><li><p>根域</p></li></ul><p>第一个被创建的域即为根域，一个域树中只能由一个根域，且根域对其他域有最高管理权。</p><h2 id="域-vs-工作组" tabindex="-1"><a class="header-anchor" href="#域-vs-工作组"><span>域 VS 工作组</span></a></h2><ol><li><p>创建方式不同，&quot;工作组&quot;可以由任何一个计算机的主人来创建，而&quot;域&quot;只能由服务器来创建。</p></li><li><p>安全机制不同，在&quot;域&quot;中有可以登录该域的帐号，这些由域管理员来建立。在&quot;工作组&quot;中不存在组帐号，只有本机上的帐号和密码。</p></li><li><p>登录方式不同，在工作组方式下，计算机启动后自动就在工作组中。登录&quot;域&quot;是要提交&quot;域用户名&quot;和&quot;密码&quot;，一旦登录，便被赋予相应的权限。</p></li></ol><h2 id="活动目录-active-directory" tabindex="-1"><a class="header-anchor" href="#活动目录-active-directory"><span>活动目录（Active Directory）</span></a></h2><p>目录是一种层次结构，用于存储有关网络上对象的信息。目录服务（例如 Active Directory 域服务 (AD DS)）提供了存储目录数据并使该数据可供网络用户和管理员使用的方法。例如，AD DS 存储有关用户帐户的信息，例如姓名、密码、电话号码等，并允许同一网络上的其他授权用户访问这些信息。</p><h2 id="ldap" tabindex="-1"><a class="header-anchor" href="#ldap"><span>LDAP</span></a></h2><p>轻量级目录访问协议（Light Directory Access Portocol】简称：LDAP）</p><h2 id="dc-cn" tabindex="-1"><a class="header-anchor" href="#dc-cn"><span>DC/CN</span></a></h2><p>DC (Domain Component)：域名组件，表示 DNS 域名中的组件</p><p>OU (Organizational Unit)：组织单位；</p><p>CN (Common Name)：通用名称，一般为用户名或计算机名；</p><h2 id="漏洞列表" tabindex="-1"><a class="header-anchor" href="#漏洞列表"><span>漏洞列表</span></a></h2><p><a href="https://github.com/infosecn1nja/AD-Attack-Defense" target="_blank" rel="noopener noreferrer">https://github.com/infosecn1nja/AD-Attack-Defense</a></p>`,24)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};